import { useState } from "react";

// ─── Sub-components ───────────────────────────────────────────────────────────

const LiveBadge = () => (
  <div className="flex items-center gap-2 mb-1">
    <span className="w-2 h-2 bg-red-400 rounded-full shadow-[0_0_8px_rgba(248,113,113,0.8)]" />
    <span className="text-[10px] font-bold uppercase tracking-widest text-red-400">
      Live Status
    </span>
  </div>
);

const LocationHero = ({ name, imageSrc, imageAlt }) => (
  <div className="rounded-2xl overflow-hidden aspect-[4/3] mb-8 relative group">
    <img
      alt={imageAlt}
      className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-700"
      src={imageSrc}
    />
    <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent" />
    <div className="absolute bottom-4 left-4">
      <LiveBadge />
      <h3 className="text-2xl font-black text-white tracking-tight">{name}</h3>
    </div>
  </div>
);

const InfoCard = ({ label, value, suffix, icon, colSpan = 1 }) => (
  <div
    className={`${colSpan === 2 ? "col-span-2" : ""
      } bg-white/5 p-4 rounded-2xl border border-white/5`}
  >
    <span className="text-[10px] text-gray-400 uppercase tracking-tighter block mb-1">
      {label}
    </span>
    <div className="flex justify-between items-end">
      <span className="text-lg font-bold text-white font-mono">
        {value}{" "}
        {suffix && (
          <span className="text-xs font-normal text-gray-500">{suffix}</span>
        )}
      </span>
      {icon && (
        <span className="material-symbols-outlined text-red-400/40">{icon}</span>
      )}
    </div>
  </div>
);

const InfoGrid = ({ coordinates, elevation, visibility }) => (
  <div className="grid grid-cols-2 gap-4 mb-8">
    <InfoCard
      colSpan={2}
      label="Current Coordinates"
      value={coordinates}
      icon="radar"
    />
    <InfoCard label="Elevation" value={elevation} suffix="AMSL" />
    <InfoCard label="Visibility" value={visibility} />
  </div>
);

const HistoricalLog = ({ text }) => (
  <div>
    <h4 className="text-sm font-bold text-white mb-3 flex items-center gap-2">
      <span className="material-symbols-outlined text-red-400 text-sm">
        history_edu
      </span>
      Historical Log
    </h4>
    <p className="text-sm text-gray-400 leading-relaxed opacity-70">{text}</p>
  </div>
);

const ExplorerAvatar = ({ src, alt }) => (
  <img
    alt={alt}
    className="inline-block h-8 w-8 rounded-full ring-2 ring-black object-cover"
    src={src}
  />
);

const ActiveExplorers = ({ explorers, extraCount }) => (
  <div>
    <h4 className="text-sm font-bold text-white mb-3 flex items-center gap-2">
      <span className="material-symbols-outlined text-red-400 text-sm">
        group
      </span>
      Active Explorers
    </h4>
    <div className="flex -space-x-3 overflow-hidden">
      {explorers.map((explorer, i) => (
        <ExplorerAvatar key={i} src={explorer.src} alt={explorer.alt} />
      ))}
      {extraCount > 0 && (
        <div className="h-8 w-8 rounded-full bg-white/10 flex items-center justify-center text-[10px] font-bold text-gray-400 ring-2 ring-black">
          +{extraCount}
        </div>
      )}
    </div>
  </div>
);

const WeatherGrid = ({ temperature, densityLabel, densityPercent }) => (
  <div className="bg-red-400/5 rounded-2xl p-4 border border-red-400/20">
    <div className="flex justify-between items-start mb-4">
      <h4 className="text-xs font-bold text-red-400 uppercase tracking-widest">
        Weather Grid
      </h4>
      <span className="material-symbols-outlined text-red-400 text-sm">
        cyclone
      </span>
    </div>
    <div className="flex items-center gap-4">
      <span className="text-4xl font-light text-white">{temperature}</span>
      <div className="flex-1 space-y-1">
        <div className="h-1 bg-white/10 rounded-full overflow-hidden">
          <div
            className="h-full bg-red-400 rounded-full transition-all duration-700"
            style={{ width: `${densityPercent}%` }}
          />
        </div>
        <span className="text-[10px] text-gray-500">{densityLabel}</span>
      </div>
    </div>
  </div>
);

const RouteButton = ({ destination, onClick }) => (
  <button
    onClick={onClick}
    className="w-full py-4 bg-white/5 hover:bg-white/10 transition-colors rounded-2xl border border-white/5 flex items-center justify-between px-6 group"
  >
    <div className="text-left">
